mapper.select:
SELECT c.COURSE_ID, b.BATCH_ID, c.COURSE_NAME, b.BATCH_NAME, b.START_DATE, b.END_DATE, b.STATUS
FROM COURSE c JOIN COURSE_BATCH b ON b.COURSE_ID = c.COURSE_ID
WHERE b.COURSE_ID = #{courseId} AND b.BATCH_ID = #{batchId}

SELECT * FROM NCS_UNIT WHERE COURSE_ID = #{courseId} AND BATCH_ID = #{batchId}
AND SUBJECT_ID = #{subjectId}
AND USE_YN = 'Y'
ORDER BY SUBJECT_ID, SORT_ORDER, UNIT_ID

mapper.update:
UPDATE NCS_UNIT_ELEMENT SET USE_YN = 'N', UPDATED_BY = #{key.updatedBy}, UPDATED_AT = NOW()
WHERE COURSE_ID = #{key.courseId} AND BATCH_ID = #{key.batchId} AND SUBJECT_ID = #{key.subjectId} AND UNIT_ID = #{key.unitId}
AND USE_YN = 'Y'

    AND ELEMENT_ID NOT IN #{id}
